using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class InventoryTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;
    public InventoryTests(WebApplicationFactory<Program> factory) => _factory = factory;

    private record LevelDto(string sku, int level);

    [Fact]
    public async Task AdjustAndReadBack()
    {
        var client = _factory.CreateClient();

        var up = await client.PostAsJsonAsync("/inventory/adjust", new { sku = "bolt", delta = 10 });
        Assert.Equal(HttpStatusCode.OK, up.StatusCode);
        var dto = await up.Content.ReadFromJsonAsync<LevelDto>();
        Assert.Equal(10, dto!.level);

        var down = await client.PostAsJsonAsync("/inventory/adjust", new { sku = "bolt", delta = -4 });
        var dto2 = await (await client.GetAsync("/inventory/bolt")).Content.ReadFromJsonAsync<LevelDto>();
        Assert.Equal(HttpStatusCode.OK, down.StatusCode);
        Assert.Equal(6, dto2!.level);
    }

    [Fact]
    public async Task NegativeAdjustmentRejectedAndUnchanged()
    {
        var client = _factory.CreateClient();
        await client.PostAsJsonAsync("/inventory/adjust", new { sku = "nail", delta = 3 });

        var over = await client.PostAsJsonAsync("/inventory/adjust", new { sku = "nail", delta = -5 });
        Assert.Equal(HttpStatusCode.Conflict, over.StatusCode);

        var dto = await (await client.GetAsync("/inventory/nail")).Content.ReadFromJsonAsync<LevelDto>();
        Assert.Equal(3, dto!.level);
    }

    [Fact]
    public async Task UnknownSkuIsZeroAndHealthWorks()
    {
        var client = _factory.CreateClient();
        var dto = await (await client.GetAsync("/inventory/ghost")).Content.ReadFromJsonAsync<LevelDto>();
        Assert.Equal(0, dto!.level);
        Assert.Equal(HttpStatusCode.OK, (await client.GetAsync("/health")).StatusCode);
    }
}

