namespace Inventory;

public class InventoryService
{
    private readonly Dictionary<string, int> _levels = new();
    private readonly object _gate = new();

    public int GetLevel(string sku)
    {
        lock (_gate)
        {
            return _levels.GetValueOrDefault(sku, 0);
        }
    }

    public int? Adjust(string sku, int delta)
    {
        lock (_gate)
        {
            int current = _levels.GetValueOrDefault(sku, 0);
            int next = current + delta;
            if (next < 0)
            {
                return null;
            }
            _levels[sku] = next;
            return next;
        }
    }
}

