using Inventory;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<InventoryService>();
var app = builder.Build();

app.MapGet("/health", () => Results.Ok(new { status = "ok" }));

app.MapPost("/inventory/adjust", (AdjustRequest req, InventoryService svc) =>
{
    int? level = svc.Adjust(req.sku, req.delta);
    if (level is null)
    {
        return Results.Conflict(new { error = "stock cannot go below zero" });
    }
    return Results.Ok(new { req.sku, level });
});

app.MapGet("/inventory/{sku}", (string sku, InventoryService svc) =>
    Results.Ok(new { sku, level = svc.GetLevel(sku) }));

app.Run();

public record AdjustRequest(string sku, int delta);

